 static void Clean(GameObject go,bool project){foreach(var mf in go.GetComponentsInChildren<MeshFilter>()){var mr=mf.GetComponent<MeshRenderer>();var old=mf.sharedMesh;if(!mr||!old||!old.isReadable)continue;if(!project&&cleaned.TryGetValue(old,out var cached)){mf.sharedMesh=cached;continue;}var vv=old.vertices;var nn=old.normals;var uu=old.uv;var vs=new List<Vector3>();var ns=new List<Vector3>();var uv=new List<Vector2>();var cache=new Dictionary<long,int>();var subs=new List<int[]>();var ms=mr.sharedMaterials;bool any=false;for(int s=0;s<old.subMeshCount;s++){bool floor=project&&s<ms.Length&&ms[s]&&ms[s].name.Contains("Floor");bool wall=project&&s<ms.Length&&ms[s]&&(ms[s].name.Contains("Coat")||ms[s].name=="BM_Pipe");var ix=old.GetTriangles(s);var dst=new List<int>();for(int i=0;i<ix.Length;i+=3){var n=Vector3.Cross(vv[ix[i+1]]-vv[ix[i]],vv[ix[i+2]]-vv[ix[i]]);if(n.sqrMagnitude<1e-16f){removed++;any=true;continue;}var wn=mf.transform.TransformDirection(n);int axis=Mathf.Abs(wn.x)>Mathf.Abs(wn.z)?0:1;for(int j=0;j<3;j++){int vi=ix[i+j];long key=(long)vi*10+(floor?4:wall?axis+1:0);if(!cache.TryGetValue(key,out int k)){k=vs.Count;cache[key]=k;vs.Add(vv[vi]);ns.Add(nn.Length==vv.Length?nn[vi]:n.normalized);var wp=mf.transform.TransformPoint(vv[vi]);uv.Add(floor?new Vector2(wp.x/2,wp.z/2):wall?new Vector2((axis==0?wp.z:wp.x)/3+serial*.173f,(wp.y+34)/3):uu.Length==vv.Length?uu[vi]:Vector2.zero);}dst.Add(k);}}subs.Add(dst.ToArray());}if(!project&&!any){cleaned[old]=old;continue;}var m=new Mesh{name="BM_Surface_"+(++serial).ToString("000"),indexFormat=IndexFormat.UInt32};m.SetVertices(vs);m.SetNormals(ns);m.SetUVs(0,uv);m.subMeshCount=subs.Count;for(int i=0;i<subs.Count;i++)m.SetTriangles(subs[i],i,false);m.RecalculateBounds();m.RecalculateTangents();AssetDatabase.CreateAsset(m,E+m.name+".asset");mf.sharedMesh=m;if(!project)cleaned[old]=m;}}
 static GameObject Put(string n,string asset,Transform p,Vector3 pos,float yaw=0,bool mesh=false,bool project=false){var src=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(!src)throw new Exception("Missing "+asset);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,p);g.name=n;g.transform.localPosition=pos;g.transform.localRotation=Quaternion.Euler(0,yaw,0);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var l in g.GetComponentsInChildren<Light>(true))UnityEngine.Object.DestroyImmediate(l);foreach(var r in g.GetComponentsInChildren<MeshRenderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>m&&mats.TryGetValue(m.name,out var v)?v:m).ToArray();r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;}Clean(g,project);if(mesh)foreach(var f in g.GetComponentsInChildren<MeshFilter>())f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;return g;}
