 static void Light(Transform parent,string n,Vector3 pos,Quaternion rot,float power,float range,bool red=false,bool shadow=false){var g=Put(n,red?E+"BC_CagedRedLamp.fbx":A+"Environment/B4/BO_SealedTaskLight.fbx",parent,pos);g.transform.localRotation=rot;var light=Group("LightSource",g.transform).AddComponent<Light>();light.transform.localPosition=red?new Vector3(0,0,.10f):new Vector3(0,-.08f,0);light.transform.localRotation=Quaternion.Euler(90,0,0);light.type=red?LightType.Point:LightType.Spot;light.spotAngle=112;light.innerSpotAngle=78;light.color=red?new Color(1,.075f,.04f):new Color(.82f,.88f,.94f);light.intensity=power;light.range=range;light.shadows=shadow?LightShadows.Soft:LightShadows.None;light.shadowBias=.01f;light.shadowNormalBias=.018f;light.shadowNearPlane=.1f;}
 static Mesh MeshAsset(string name,List<Vector3> verts,List<int> indices,List<Vector2> uv){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(verts);m.SetTriangles(indices,0);m.SetUVs(0,uv);m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,E+name+".asset");return m;}
 static Vector3 At(List<Vector3> ps,float d){for(int i=1;i<ps.Count;i++){float l=Vector3.Distance(ps[i-1],ps[i]);if(d<=l)return Vector3.Lerp(ps[i-1],ps[i],d/l);d-=l;}return ps.Last();}
 static void Guide(Transform p,JToken t,List<Vector3> ps,float length){string code=((string)t["id"]).Split('-')[1];foreach(int side in new[]{-1,1}){string dest=(string)t[side<0?"a":"b"];var vs=new List<Vector3>();var ix=new List<int>();var uv=new List<Vector2>();int n=Mathf.CeilToInt((length-3)/.5f);for(int i=0;i<=n;i++){float d=1.5f+(length-3)*i/n;var c=At(ps,d);var dir=(At(ps,d+.02f)-At(ps,d-.02f)).normalized;var right=Vector3.Cross(Vector3.up,dir);foreach(float w in new[]{-.0275f,.0275f}){vs.Add(c+right*(side*.14f+w)+Vector3.up*.012f);uv.Add(new Vector2(w<0?0:1,d));}if(i<n){int k=i*2;ix.AddRange(new[]{k,k+2,k+1,k+1,k+2,k+3});}}var g=Group("B2_"+code+"_GuideTo_"+dest,p);g.AddComponent<MeshFilter>().sharedMesh=MeshAsset("BM_"+code+"_GuideTo_"+dest,vs,ix,uv);g.AddComponent<MeshRenderer>().sharedMaterial=Mat("BM_Line_"+dest);
