 public static object Run(){var scene=SceneManager.GetActiveScene();if(scene.isDirty||Application.isPlaying||!scene.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");if(scene.GetRootGameObjects().Any(g=>g.name=="B2_MachineryNetwork"))throw new Exception("Already extended: repair only");var old=scene.GetRootGameObjects().Single(g=>g.name=="B2_C02_CoolingSector");File.WriteAllText(H+"C02_before.json",JsonConvert.SerializeObject(old.GetComponentsInChildren<Transform>(true).Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),t.name,pos=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},rot=new[]{t.localRotation.x,t.localRotation.y,t.localRotation.z,t.localRotation.w},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z},active=t.gameObject.activeSelf}),Formatting.Indented));Materials();var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));root=new GameObject("B2_MachineryNetwork").transform;root.position=new Vector3(0,-34,0);
 foreach(var r in plan["rooms"]){string id=(string)r["id"];float rad=(float)r["r"];bool core=(string)r["kind"]=="core";if(id=="C02"){var a=old.transform.Find("Architecture");foreach(var t in a.GetComponentsInChildren<Transform>(true).Where(t=>t.parent==a&&(t.name=="B2_C02_Shell"||t.name=="B2_C02_Lining"||t.name.Contains("ClosedDoor")||t.name.Contains("Portal"))))t.gameObject.SetActive(false);foreach(var t in old.transform.Find("Lighting").GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("B2_C02_DoorLamp")))t.gameObject.SetActive(false);Put("B2_C02_PipeOpeningShell",E+"BM_C02_Shell.fbx",a,Vector3.zero,mesh:true,project:true);Put("B2_C02_PipeOpeningLining",E+"BM_C02_Lining.fbx",a,Vector3.zero,project:true);continue;}
 var room=Group("B2_"+id+"_Sector",root).transform;room.localPosition=new Vector3((float)r["x"],0,-(float)r["v"]);var arch=Group("Architecture",room).transform;var eq=Group("Equipment",room).transform;var lamps=Group("Lighting",room).transform;
 foreach(string part in new[]{"Shell","Floor","Lining","Services"})Put("B2_"+id+"_"+part,E+"BM_"+id+"_"+part+".fbx",arch,Vector3.zero,mesh:part=="Shell"||part=="Floor",project:part!="Services");foreach(var p in plan["placements"].Where(p=>(string)p["room"]==id))Equipment(p,eq);
 if(!core){int count=rad>=8?8:6;for(int i=0;i<count;i++){float a=(22.5f+360f*i/count)*Mathf.Deg2Rad;var normal=new Vector3(Mathf.Cos(a)*.55f,.835f,Mathf.Sin(a)*.55f).normalized;var tangent=new Vector3(-Mathf.Sin(a),0,Mathf.Cos(a));Light(lamps,"B2_"+id+"_TaskLight_"+i,normal*(rad-.24f),Quaternion.LookRotation(Vector3.Cross(tangent,normal),normal),4+rad*.25f,rad*1.6f,shadow:i%3==0);}for(int i=0;i<4;i++){float a=(i*90+40)*Mathf.Deg2Rad;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Light(lamps,"B2_"+id+"_RedService_"+i,dir*(Mathf.Sqrt(rad*rad-3.05f*3.05f)-.10f)+Vector3.up*3.05f,Quaternion.LookRotation(-dir),.65f,5,true);}var fill=Group("B2_"+id+"_Bounce",lamps).AddComponent<Light>();fill.type=LightType.Point;fill.transform.localPosition=Vector3.up*3.7f;fill.color=new Color(.60f,.66f,.72f);fill.intensity=.65f;fill.range=rad*1.6f;
 }else{for(int i=0;i<4;i++){float a=(45+90*i)*Mathf.Deg2Rad;var d=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Light(lamps,"B2_"+id+"_CoreLight_"+i,d*4.75f+Vector3.up*3.6f,Quaternion.FromToRotation(Vector3.up,(d*.8f+Vector3.up*.6f).normalized),3.2f,9);}if(id=="VA"||id=="VB"){Put("B2_"+id+"_StairsToB1",E+"BM_VerticalStairs.fbx",arch,Vector3.zero,mesh:true);for(int i=0;i<8;i++)Light(lamps,"B2_"+id+"_LandingLight_"+i,new Vector3(i%2==0?-4.75f:4.75f,2*i+2.9f,0),Quaternion.FromToRotation(Vector3.up,new Vector3(i%2==0?-1:1,.45f,0).normalized),2.8f,8);var upper=Put("B2_"+id+"_UpperClosedDoor",A+"Environment/B4/BO_ClosedVaultDoor.fbx",arch,new Vector3(0,16,-4.5f),mesh:true);upper.transform.localScale=new Vector3(.5f,.8f,1);}else{Put("B2_VL_CargoLift",E+"BM_CargoLift.fbx",arch,Vector3.zero,mesh:true);Light(lamps,"B2_VL_CabinLight",new Vector3(0,3.67f,-1.25f),Quaternion.identity,2.5f,5);}}}
 var halls=Group("B2_PipeCorridors",root).transform;var guides=Group("B2_DestinationGuidance",root).transform;foreach(var t in plan["tunnels"]){string code=((string)t["id"]).Split('-')[1];var c=Group("B2_"+code+"_"+(string)t["a"]+"_"+(string)t["b"],halls).transform;Put("B2_"+code+"_TunnelShell",E+"BM_"+code+"_Shell.fbx",c,Vector3.zero,mesh:true,project:true);Put("B2_"+code+"_PipeFlangesAndServices",E+"BM_"+code+"_Finish.fbx",c,Vector3.zero);var ps=t["path"].Select(p=>new Vector3((float)p[0],0,-(float)p[1])).ToList();float length=0;for(int i=1;i<ps.Count;i++)length+=Vector3.Distance(ps[i-1],ps[i]);for(int i=0;i<=Mathf.CeilToInt((length-3)/7);i++){float d=1.8f+(length-3.6f)*i/Mathf.CeilToInt((length-3)/7);var pos=At(ps,d);var dir=(At(ps,d+.04f)-At(ps,d-.04f)).normalized;Light(c,"B2_"+code+"_PipeWorkLight_"+i,pos+Vector3.up*3.71f,Quaternion.LookRotation(dir),3.0f,9.8f);if(i%2==0){var right=Vector3.Cross(Vector3.up,dir);Light(c,"B2_"+code+"_RedMarker_"+i,pos+right*2.10f+Vector3.up*2.55f,Quaternion.LookRotation(-right),.42f,4.0f,true);}}Guide(guides,t,ps,length);}
